// A photo, full bleed, with its caption over a gradient.
export function get(app) {
  const photo = frameos.fetchImage(app.config.url)
  return (
    <div className="relative bg-black text-white">
      <img className="absolute inset-0 w-full h-full object-cover" src={photo} />
      <div className="absolute inset-x-0 bottom-0 h-1/2 bg-gradient-to-t from-black/80 to-transparent" />
      <div className="absolute left-8 bottom-8 right-8 flex items-end justify-between">
        <div className="flex flex-col gap-1">
          <span className="text-sm uppercase text-white/70 font-semibold">Holidays, 2023</span>
          <span className="text-4xl font-bold">Barbecue at the South Pole</span>
          <span className="text-lg text-white/80">Everyone came, nobody was cold</span>
        </div>
        <div className="flex gap-2 items-center">
          {[0, 1, 2, 3, 4].map((i) => <div className={`rounded-full ${i === 2 ? 'w-6 h-2 bg-white' : 'w-2 h-2 bg-white/50'}`} />)}
        </div>
      </div>
    </div>
  )
}
